schemas.schema-1-systematic.prisma:
/// Temporary guest accounts identified by device session data. Stores guest
/// identity information and tracks session metadata for unauthenticated
/// users. Used to maintain continuity for guests who may later register as
/// members.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique identifier for the guest's device/browser session.
  device_id String

  /// IP address of the guest at session creation.
  ip String

  /// Browser user agent string for device identification.
  user_agent String?

  /// Timestamp when the guest account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was soft-deleted (nullable if not
  /// deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions todo_app_guest_sessions[]

  //----
  // INDEXES
  //----
  @@unique([device_id])
  @@index([created_at])
  @@index([deleted_at])
}

/// Temporary session tokens for guest access without authentication. Each
/// guest user has multiple sessions that track connection metadata and
/// expiration. Sessions expire after a configured time period and are used
/// for security auditing and session management.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_guest_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged guest's {@link todo_app_guests.id}.
  todo_app_guest_id String @db.Uuid

  /// Client IP address at session creation.
  ip String

  /// Browser user agent string for session identification.
  user_agent String?

  /// Referrer URL when session was created.
  referrer String?

  /// Session creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Session expiration timestamp. Sessions are invalid after this time.
  expired_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. If null, session is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  guest todo_app_guests @relation(fields: [todo_app_guest_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([todo_app_guest_id, created_at])
}

/// Registered member accounts with email/password authentication
/// credentials. Members can create, edit, complete, and delete their own
/// todos. Each member has exactly one profile and can have multiple
/// sessions. Account lifecycle includes registration, authentication,
/// password change, and permanent deletion (cascades to all member's todos
/// and profile).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Member account identifier.
  id String @id @db.Uuid

  /// Member's user account. {@link todo_app_users.id}.
  todo_app_user_id String @db.Uuid

  /// Member's display profile. {@link todo_app_profiles.id}.
  todo_app_profile_id String @db.Uuid

  /// Unique email address for authentication. Used as login identifier.
  email String

  /// Securely hashed password for authentication.
  password_hash String

  /// When the member account was created.
  created_at DateTime @db.Timestamptz

  /// When the member account was last updated.
  updated_at DateTime @db.Timestamptz

  /// When the member account was permanently deleted. Null indicates active
  /// account.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  user todo_app_users @relation(fields: [todo_app_user_id], references: [id], onDelete: Cascade)
  profile todo_app_profiles @relation(fields: [todo_app_profile_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions todo_app_member_sessions[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@unique([todo_app_user_id])
  @@unique([todo_app_profile_id])
  @@index([created_at])
  @@index([deleted_at])
}

/// JWT session tokens for member authentication with access and refresh
/// support. Each session tracks authentication tokens, connection metadata,
/// and session lifecycle including creation, expiration, and last usage
/// timestamps.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_member_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Member's {@link todo_app_members.id}. References the authenticated member
  /// account for this session.
  todo_app_member_id String @db.Uuid

  /// JWT access token for API authentication. Used for authorizing requests on
  /// behalf of the member.
  access_token String

  /// JWT refresh token for obtaining new access tokens without
  /// re-authentication.
  refresh_token String

  /// Expiration timestamp for the access token. Access tokens typically have
  /// short validity periods.
  access_expires_at DateTime @db.Timestamptz

  /// Expiration timestamp for the refresh token. Refresh tokens have longer
  /// validity periods to enable session persistence.
  refresh_expires_at DateTime @db.Timestamptz

  /// IP address of the client that initiated this session. Used for security
  /// monitoring and anomaly detection.
  ip String

  /// HTTP User-Agent header from the client's request. Used for device
  /// identification and security tracking.
  user_agent String?

  /// HTTP Referer header from the client's request. Indicates the source of
  /// the authentication request.
  referrer String?

  /// Timestamp of the last API request made with this session. Used for
  /// session activity monitoring and cleanup.
  last_used_at DateTime? @db.Timestamptz

  /// Creation timestamp of this session record.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp of this session record.
  updated_at DateTime @db.Timestamptz

  /// Session expiration timestamp. After this time, the session should be
  /// considered invalid.
  expired_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  member todo_app_members @relation(fields: [todo_app_member_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([access_token])
  @@unique([refresh_token])
  @@index([todo_app_member_id, created_at])
  @@index([access_expires_at])
  @@index([refresh_expires_at])
  @@index([expired_at])
  @@index([last_used_at])
}

