schemas.schema-4-todos.prisma:
/// Core todo entity with user ownership, title, optional description, dates,
/// completion status, and soft delete state.
///
/// Todos represent individual tasks or items that users create, edit,
/// complete, and manage through a complete lifecycle including soft deletion
/// to trash and restoration.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_todos {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner user's {@link todo_app_users.id}.
  todo_app_user_id String @db.Uuid

  /// Todo title (1-500 characters, required).
  title String

  /// Optional todo description.
  description String?

  /// Optional start date for the todo.
  start_date DateTime? @db.Timestamptz

  /// Optional due date for the todo.
  due_date DateTime? @db.Timestamptz

  /// Whether the todo is marked as complete (default false).
  is_complete Boolean

  /// Whether the todo is in trash (soft deleted).
  is_trashed Boolean

  /// When this todo was created.
  created_at DateTime @db.Timestamptz

  /// When this todo was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this todo was permanently deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  user todo_app_users @relation(fields: [todo_app_user_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  editHistoryEntries todo_app_todo_edits[]
  trashEntry todo_app_todo_trashes?

  //----
  // INDEXES
  //----
  @@index([todo_app_user_id, created_at])
  @@index([todo_app_user_id, start_date])
  @@index([todo_app_user_id, due_date])
  @@index([todo_app_user_id, is_complete])
  @@index([todo_app_user_id, is_trashed])
}

/// Records all edits to todo items including timestamps and field-level
/// changes. Each edit captures the previous and new values for title,
/// description, start date, and due date. Edits are automatically created
/// whenever a todo is modified and provide an audit trail of all changes
/// made by users.
///
/// This table follows First Normal Form (1NF) with atomic values, Second
/// Normal Form (2NF) where all non-key attributes depend on the primary key,
/// and Third Normal Form (3NF) without transitive dependencies. Each edit
/// history entry is immutable once created and cannot exist independently of
/// a todo.
///
/// Relationships:
/// - Each edit history entry belongs to exactly one todo (todo_app_todos)
/// - A todo can have many edit history entries (1:N relationship)
/// - Editing capabilities are captured through separate previous/new field
/// pairs
///
/// Reference: @link todo_app_todos.id
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_todo_edits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target todo this edit history entry belongs to. {@link todo_app_todos.id}.
  todo_id String @db.Uuid

  /// Timestamp when the edit was made. Records the exact date and time of the
  /// edit operation.
  edited_at DateTime @db.Timestamptz

  /// The title value before this edit. NULL if title was not changed in this
  /// edit.
  previous_title String?

  /// The title value after this edit. NULL if title was not changed in this
  /// edit.
  new_title String?

  /// The description value before this edit. NULL if description was not
  /// changed in this edit.
  previous_description String?

  /// The description value after this edit. NULL if description was not
  /// changed in this edit.
  new_description String?

  /// The start date value before this edit. NULL if start date was not changed
  /// in this edit.
  previous_start_date DateTime? @db.Timestamptz

  /// The start date value after this edit. NULL if start date was not changed
  /// in this edit.
  new_start_date DateTime? @db.Timestamptz

  /// The due date value before this edit. NULL if due date was not changed in
  /// this edit.
  previous_due_date DateTime? @db.Timestamptz

  /// The due date value after this edit. NULL if due date was not changed in
  /// this edit.
  new_due_date DateTime? @db.Timestamptz

  /// Creation timestamp. Automatically set when the edit history entry is
  /// created.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp. Automatically updated whenever the record is
  /// modified.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  todo todo_app_todos @relation(fields: [todo_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  historyEntries todo_app_edit_history_entries[]

  //----
  // INDEXES
  //----
  @@index([todo_id, created_at])
}

/// Soft delete tracking for todos. Records when a todo was deleted via soft
/// delete, whether it has been restored from trash, and when it was
/// permanently deleted. Each todo can have at most one trash record. Used to
/// implement the trash system where deleted todos can be restored or
/// permanently removed along with their edit history.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_todo_trashes {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Deleted todo's {@link todo_app_todos.id}. Unique constraint ensures 1:1
  /// relationship.
  todo_id String @db.Uuid

  /// When the todo was soft-deleted. Non-null indicates the todo is currently
  /// in trash state.
  deleted_at DateTime @db.Timestamptz

  /// When the todo was restored from trash. Nullable - non-null means todo was
  /// restored from trash at this time.
  restored_at DateTime? @db.Timestamptz

  /// When the todo was permanently deleted from trash. Nullable - non-null
  /// means permanent deletion occurred at this time.
  permanently_deleted_at DateTime? @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  trash todo_app_todos @relation(fields: [todo_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([todo_id])
  @@index([deleted_at])
  @@index([permanently_deleted_at])
}

schemas.schema-5-edithistory.prisma:
/// Records all edits to todos with timestamps and changed field values.
/// Automatically created on every todo edit, captures only fields that
/// actually changed (title, description, start date, due date) with their
/// previous and new values. Each edit creates exactly one history entry.
/// History entries are immutable and sorted from most recent to oldest by
/// timestamp.
///
/// @namespace EditHistory
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_edit_history_entries {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Edit record reference. {@link todo_app_todo_edits.id}.
  todo_app_todo_edit_id String @db.Uuid

  /// Edit timestamp when this history entry was created.
  created_at DateTime @db.Timestamptz

  /// Previous title value if title was changed, null otherwise.
  previous_title String?

  /// New title value if title was changed, null otherwise.
  new_title String?

  /// Previous description value if description was changed, null otherwise.
  previous_description String?

  /// New description value if description was changed, null otherwise.
  new_description String?

  /// Previous start date value if start date was changed, null otherwise.
  previous_start_date DateTime? @db.Timestamptz

  /// New start date value if start date was changed, null otherwise.
  new_start_date DateTime? @db.Timestamptz

  /// Previous due date value if due date was changed, null otherwise.
  previous_due_date DateTime? @db.Timestamptz

  /// New due date value if due date was changed, null otherwise.
  new_due_date DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  edit todo_app_todo_edits @relation(fields: [todo_app_todo_edit_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([todo_app_todo_edit_id, created_at], map: "todo_app_edit_history_entries_todo_app_todo_edit_id_cr_eb21a129")
}

